steps.run:
$version = node -p "require('./desktop/package.json').version"
if ($LASTEXITCODE -ne 0) { throw "Unable to read desktop package version" }
$fakeCipher = (& go run ./backend -encrypt-riot-key 'RGAPI-00000000-0000-0000-0000-000000000000').Trim()
if ($LASTEXITCODE -ne 0 -or -not $fakeCipher) { throw "Fake key encryption failed" }
./build-desktop-windows.ps1 -Version $version -KeyMode public -SkipTestsInCI -RiotAPIKeyCipher $fakeCipher
if ($LASTEXITCODE -ne 0) { throw "Desktop build failed" }
$env:DEEP_LEGENDS_KEY_MODE='public'
node desktop/verify-embedded-riot-key.cjs --expect-fake
if ($LASTEXITCODE -ne 0) { throw "Fake embedded key verification failed" }

Get-Content dist/desktop/SHA256SUMS-public.txt | ForEach-Object {
  $parts = $_ -split '  ', 2
  $actual = (Get-FileHash -Algorithm SHA256 (Join-Path dist/desktop $parts[1])).Hash.ToLowerInvariant()
  if ($actual -ne $parts[0]) { throw "Checksum mismatch: $($parts[1])" }
}

if (-not (Get-Command gcc -ErrorAction SilentlyContinue)) {
  $compiler = @('C:\mingw64\bin', 'C:\msys64\mingw64\bin') | Where-Object { Test-Path (Join-Path $_ 'gcc.exe') } | Select-Object -First 1
  if (-not $compiler) { throw 'Windows race compiler is unavailable' }
  $compiler | Out-File -FilePath $env:GITHUB_PATH -Encoding utf8 -Append
}

go mod download
if ($LASTEXITCODE -ne 0) { throw 'R277 backend dependencies failed' }
Push-Location installer
try {
  go mod download
  if ($LASTEXITCODE -ne 0) { throw 'R277 installer dependencies failed' }
} finally { Pop-Location }

$env:R276_OFFLINE_OUTPUT="$env:RUNNER_TEMP/r276-backend-offline.json"
node scripts/r276-offline.cjs -- node scripts/run-ci-tests.cjs go backend
if ($LASTEXITCODE -ne 0) { throw "Windows backend tests or pass inventory failed" }

$env:R276_OFFLINE_OUTPUT="$env:RUNNER_TEMP/r276-installer-offline.json"
node scripts/r276-offline.cjs -- node scripts/run-ci-tests.cjs go installer
if ($LASTEXITCODE -ne 0) { throw "Windows installer tests or pass inventory failed" }

go test -c -o "$env:RUNNER_TEMP/r252-r104.test.exe" ./backend
if ($LASTEXITCODE -ne 0) { throw "R104 soak compilation failed" }
python scripts/r252-r104-soak.py --binary "$env:RUNNER_TEMP/r252-r104.test.exe" --output "$env:RUNNER_TEMP/r252-r104-windows" --iterations 30
if ($LASTEXITCODE -ne 0) { throw "R104 soak failure; original timelines retained" }

node scripts/run-ci-tests.cjs node --expected-tests=2 --test-name-pattern="R86 Windows release|R222 Windows" desktop/release-quality-gates.test.cjs
if ($LASTEXITCODE -ne 0) { throw "Windows release gates failed" }
node scripts/run-ci-tests.cjs node --expected-tests=1 --test-name-pattern="setup-only Windows CI skip" scripts/setup-only-build.test.cjs
if ($LASTEXITCODE -ne 0) { throw "Windows setup-only guards failed" }
node scripts/run-ci-tests.cjs node --expected-tests=2 scripts/r82-startup-ab-script.test.cjs
if ($LASTEXITCODE -ne 0) { throw "PowerShell script guards failed" }
